<?php require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/admin-auth.php'; $pdo=getPDO(); requireAdminLogin(); if(isset($_GET['delete'])){$s=$pdo->prepare('DELETE FROM customers WHERE id=?');$s->execute([(int)$_GET['delete']]);header('Location: customers.php');exit;} $rows=$pdo->query('SELECT id,name,email,mobile,created_at FROM customers ORDER BY created_at DESC')->fetchAll(); ?><!doctype html><html><head><title>Customers</title><link rel="stylesheet" href="../css/style.css"></head><body><?php include 'partials/sidebar.php'; ?><main class="section"><div class="container"><h1>Customers</h1><table class="admin-table"><tr><th>ID</th><th>Name</th><th>Email</th><th>Mobile</th><th>Registered</th><th>Action</th></tr><?php foreach($rows as $r): ?><tr><td><?php echo $r['id']; ?></td><td><?php echo htmlspecialchars($r['name']); ?></td><td><?php echo htmlspecialchars($r['email']); ?></td><td><?php echo htmlspecialchars($r['mobile']); ?></td><td><?php echo $r['created_at']; ?></td><td><a class="btn btn-small btn-secondary" onclick="return confirm('Delete customer and related records?')" href="?delete=<?php echo $r['id']; ?>">Delete</a></td></tr><?php endforeach; ?></table></div></main></body></html>
